mapper.update:
update course
course_name = #{courseName}, teacher_id = #{teacherId}, classroom_id = #{classroomId}, weekday = #{weekday}, start_week = #{startWeek}, end_week = #{endWeek},
where course_id = #{courseId}

mapper.select:
select c.*, u.real_name as teacher_name from course c left join user u on c.teacher_id = u.id
and c.course_id like concat('%', #{courseId}, '%')
and c.course_name like concat('%', #{courseName}, '%')
and c.teacher_id = #{teacherId}
and c.classroom_id = #{classroomId}
order by c.create_time desc
